            const medRows = rows.filter(r => r.measurement === 'medications');
            const weightSeries = toDaySeries(weightRows);
            // A medication "event" is a dosage-era start — only weekly/
            // biweekly meds (frequency_days > 1) are relevant to this
            // analysis's premise (Ward's own framing: "some medications
            // are weekly/bi-weekly").
            const cadenceEvents = medRows
                .filter(r => Number(r.value) > 1)
                .map(r => ({ date: easternDateKey(r.time), medication: (r.tags && r.tags.name) || 'unknown', frequency_days: Number(r.value) }));
            // For each cadence event, weight 3 days before vs 3 days after.
            const windows = cadenceEvents.map(ev => {
                const evT = new Date(ev.date).getTime();
                const before = weightSeries.filter(p => { const d = new Date(p.date).getTime() - evT; return d >= -3 * 86400000 && d < 0; });
                const after = weightSeries.filter(p => { const d = new Date(p.date).getTime() - evT; return d >= 0 && d <= 3 * 86400000; });
                return {
                    date: ev.date, medication: ev.medication, frequency_days: ev.frequency_days,
                    weight_before_avg: mean(before.map(p => p.value)),
                    weight_after_avg: mean(after.map(p => p.value)),
