            rows.filter(r => r.measurement === 'incidents').forEach(r => { const d = easternDateKey(r.time); incidentDays[d] = (incidentDays[d] || 0) + 1; });
            const series = {
                incidents: Object.entries(incidentDays).sort().map(([date, value]) => ({ date, value })),
                alcohol: toDaySeries(rows.filter(r => r.field === 'alcohol_drinks')),
                caffeine: toDaySeries(rows.filter(r => r.field === 'caffeine_servings')),
                weight: toDaySeries(rows.filter(r => r.field === 'weight')),
                mood: toDaySeries(rows.filter(r => r.field === 'mood_rating')),
                sleep_efficiency: toDaySeries(rows.filter(r => r.field === 'efficiency')),
                hrv: toDaySeries(rows.filter(r => r.field === 'average_hrv')),
                exercise_minutes: toDaySeries(rows.filter(r => r.field === 'exercise_minutes')),
            };
            const keys = Object.keys(series);
            const matrix = [];
            keys.forEach(a => keys.forEach(b2 => {
                if (a >= b2) return; // upper triangle only, avoid duplicate/self pairs
                const { xs, ys } = alignByDay(series[a], series[b2]);
                matrix.push({ a, b: b2, correlation: pearsonCorrelation(xs, ys), paired_days: xs.length });
            }));
            return { label: 'Full correlation matrix', factors: keys, matrix, note: 'Small-dataset correlations — treat as exploratory, not statistically confirmed, until data volume grows (Ward said as much when this analysis was planned, PLAN.md section 11).' };
        },
