    unreported_anxiety_detection: {
        n: 18,
        flux: (b, s, e) => 'from(bucket: "' + b + '")\n' +
            '  |> range(start: ' + s + (e ? ', stop: ' + e : '') + ')\n' +
            '  |> filter(fn: (r) => r._measurement == "incidents" or (r._measurement == "oura_sleep" and (r._field == "average_hrv" or r._field == "lowest_heart_rate" or r._field == "efficiency") and (r.type == "long_sleep" or r.type == "sleep")))\n' +
            '  |> sort(columns: ["_time"])',
        shape: rows => {
            const incidentDays = new Set(rows.filter(r => r.measurement === 'incidents').map(r => easternDateKey(r.time)));
            const hrv = toDaySeries(rows.filter(r => r.field === 'average_hrv'));
            const rhr = toDaySeries(rows.filter(r => r.field === 'lowest_heart_rate'));
            const eff = toDaySeries(rows.filter(r => r.field === 'efficiency'));
            function baseline(series, onIncidentDays) {
                const vals = series.filter(p => onIncidentDays === incidentDays.has(p.date)).map(p => p.value);
                return { avg: mean(vals), n: vals.length };
            }
            const hrvIncident = baseline(hrv, true), hrvNormal = baseline(hrv, false);
            const rhrIncident = baseline(rhr, true), rhrNormal = baseline(rhr, false);
            const effIncident = baseline(eff, true), effNormal = baseline(eff, false);
            // Flag a NON-incident day as a possible unreported-anxiety day
            // if HRV is below the incident-day average AND resting HR is
            // above the incident-day average AND sleep efficiency is
            // below the incident-day average — all three, deliberately
            // conservative (fewer false positives) since this is a
            // pattern-match against a small baseline, not a diagnosis.
            const flagged = [];
            hrv.forEach(p => {
                if (incidentDays.has(p.date)) return;
                const r = rhr.find(x => x.date === p.date);
                const e = eff.find(x => x.date === p.date);
                if (!r || !e || hrvIncident.avg === null || rhrIncident.avg === null || effIncident.avg === null) return;
                if (p.value <= hrvIncident.avg && r.value >= rhrIncident.avg && e.value <= effIncident.avg) {
                    flagged.push({ date: p.date, hrv: p.value, resting_hr: r.value, sleep_efficiency: e.value });
                }
            });
            return {
                label: 'Unreported-anxiety detection',
                incident_day_baseline: { hrv: hrvIncident, resting_hr: rhrIncident, sleep_efficiency: effIncident },
                normal_day_baseline: { hrv: hrvNormal, resting_hr: rhrNormal, sleep_efficiency: effNormal },
                flagged_days: flagged,
                note: 'Pattern-match against known incident days, not a diagnosis — needs real incident history to mean anything, per PLAN.md section 11 analysis #18. Likely to want more data before trusting.',
            };
        },
    },
    bedtime_wake_time_trend: {
